// Full checkpoint diagnostic decoder. All projection GEMMs execute on Ascend;
// scalar/state math stays explicit C++ until the integrated numerical gate passes.
#include "openpangu_weights.h"
#include <aclnnop/aclnn_dynamic_quant.h>
#include <aclnnop/aclnn_quant_matmul_v5.h>
#include <hccl/hccl.h>
#include <array>
#include <iostream>
#include <thread>
#include <numeric>
namespace pangu {
using V=std::vector<float>;using openpangu::checked;using openpangu::DeviceTensor;
float frombf(uint16_t b){uint32_t n=uint32_t(b)<<16;float x;std::memcpy(&x,&n,4);return x;}
uint16_t tobf(float x){uint32_t n;std::memcpy(&n,&x,4);return uint16_t((n+0x7fff+((n>>16)&1))>>16);}
float roundbf(float x){return frombf(tobf(x));}
std::vector<uint16_t> packed(const V&x){std::vector<uint16_t>b;for(float v:x)b.push_back(tobf(v));return b;}
V unpacked(const std::vector<uint16_t>&b){V x;for(auto v:b)x.push_back(frombf(v));return x;}
struct View{aclTensor*t=nullptr;View(void*p,std::vector<int64_t>shape,aclDataType type,bool transpose=false){auto storage=shape;std::vector<int64_t>s(shape.size(),1);for(int i=int(s.size())-2;i>=0;--i)s[i]=s[i+1]*shape[i+1];if(transpose){std::swap(shape[0],shape[1]);std::swap(s[0],s[1]);}t=aclCreateTensor(shape.data(),shape.size(),type,s.data(),0,ACL_FORMAT_ND,storage.data(),storage.size(),p);if(!t)throw std::runtime_error("weight view");}~View(){if(t)aclDestroyTensor(t);}};
struct Decoder {
 int rank;aclrtStream stream=nullptr;HcclComm comm=nullptr;openpangu::ResidentWeights weights;
 std::map<std::string,V> host;std::map<std::string,std::array<V,2>> history;
 std::array<std::vector<V>,46> cache;std::array<std::vector<V>,46> sinks;
 void*workspace=nullptr;uint64_t capacity=0;
 Decoder(const openpangu::LoadPlan&p,const std::string&root,HcclRootInfo&info):rank(p.rank),weights(p,root){checked(aclrtCreateStream(&stream),"stream");checked(HcclCommInitRootInfo(8,&info,rank,&comm),"HCCL");}
 ~Decoder(){if(stream)aclrtSynchronizeStream(stream);if(workspace)aclrtFree(workspace);if(comm)HcclCommDestroy(comm);if(stream)aclrtDestroyStream(stream);}
 void run(openpangu::Launcher f,uint64_t bytes,aclOpExecutor*e){if(bytes>capacity){if(workspace)checked(aclrtFree(workspace),"workspace free");capacity=bytes;checked(aclrtMalloc(&workspace,capacity,ACL_MEM_MALLOC_HUGE_FIRST),"workspace");}checked(f(workspace,bytes,e,stream),"operator");checked(aclrtSynchronizeStream(stream),"fence");}
 openpangu::ResidentWeight& w(const std::string&n){auto it=weights.tensors.find(n);if(it==weights.tensors.end())throw std::runtime_error("missing weight "+n);return *it->second;}
 const V& cpu(const std::string&n){auto it=host.find(n);if(it!=host.end())return it->second;auto&a=w(n);V v;if(a.bytes>8*1024*1024)throw std::runtime_error("scalar weight staging bound "+n);if(a.dtype=="F32"){v.resize(a.bytes/4);checked(aclrtMemcpy(v.data(),a.bytes,a.data,a.bytes,ACL_MEMCPY_DEVICE_TO_HOST),"float weight");}else if(a.dtype=="BF16"){std::vector<uint16_t>b(a.bytes/2);checked(aclrtMemcpy(b.data(),a.bytes,a.data,a.bytes,ACL_MEMCPY_DEVICE_TO_HOST),"BF16 weight");v=unpacked(b);}else throw std::runtime_error("scalar dtype");return host.emplace(n,std::move(v)).first->second;}
 V gather(const V&x){DeviceTensor a({int64_t(x.size())},ACL_BF16,2),b({int64_t(x.size()*8)},ACL_BF16,2);a.upload(packed(x));checked(HcclAllGather(a.data,b.data,x.size(),HCCL_DATA_TYPE_BFP16,comm,stream),"all gather");checked(aclrtSynchronizeStream(stream),"gather fence");return unpacked(b.read<uint16_t>());}
 V sum(const V&x){DeviceTensor a({int64_t(x.size())},ACL_FLOAT,4),b({int64_t(x.size())},ACL_FLOAT,4);a.upload(x);checked(HcclAllReduce(a.data,b.data,x.size(),HCCL_DATA_TYPE_FP32,HCCL_REDUCE_SUM,comm,stream),"all reduce");checked(aclrtSynchronizeStream(stream),"reduce fence");return b.read<float>();}
 V matrix(const V&x,void*weight,int rows,int cols,bool transposed=true){int output=transposed?rows:cols;DeviceTensor input({1,int64_t(x.size())},ACL_BF16,2),out({1,output},ACL_BF16,2);input.upload(packed(x));View view(weight,{rows,cols},ACL_BF16,transposed);uint64_t bytes=0;aclOpExecutor*e=nullptr;checked(aclnnMatmulGetWorkspaceSize(input.tensor,view.t,out.tensor,0,&bytes,&e),"BF16 matmul prepare");run(aclnnMatmul,bytes,e);return unpacked(out.read<uint16_t>());}
 V linear(const std::string&name,const V&x,bool distributed=false){auto&a=w(name+".weight");int n=a.source.shape[0],k=a.source.shape[1];if(int(x.size())!=k)throw std::runtime_error("linear shape "+name);V result;
  if(a.dtype=="BF16")result=matrix(x,a.data,n,k);
  else {auto&s=w(name+".weight_scale");DeviceTensor input({1,k},ACL_BF16,2),quant({1,k},ACL_INT8,1),scale({1},ACL_FLOAT,4),out({1,n},ACL_BF16,2);input.upload(packed(x));View weight(a.data,{n,k},ACL_INT8),scales(s.data,{n},ACL_FLOAT);uint64_t bytes=0;aclOpExecutor*e=nullptr;checked(aclnnDynamicQuantGetWorkspaceSize(input.tensor,nullptr,quant.tensor,scale.tensor,&bytes,&e),"quant prepare");run(aclnnDynamicQuant,bytes,e);checked(aclnnQuantMatmulV5GetWorkspaceSize(quant.tensor,weight.t,scale.tensor,scales.t,nullptr,nullptr,nullptr,nullptr,nullptr,false,true,0,out.tensor,&bytes,&e),"int8 matmul prepare");run(aclnnQuantMatmulV5,bytes,e);result=unpacked(out.read<uint16_t>());}
  return distributed?gather(result):result;
 }
 V norm(const V&x,const std::string&name){auto&gamma=cpu(name+".weight");if(gamma.size()!=x.size())throw std::runtime_error("norm shape");float square=0;for(float v:x)square+=v*v;float r=1/std::sqrt(square/x.size()+1e-5f);V y(x.size());for(size_t j=0;j<x.size();++j)y[j]=roundbf(x[j]*r*gamma[j]);return y;}
 V mome(V x,const std::string&name,int position){auto&coef=cpu(name+".weight");auto&h=history[name];if(h[0].empty()){h[0].assign(x.size(),0);h[1]=h[0];}V original=x;if(position>=2)for(size_t j=0;j<x.size();++j)x[j]=roundbf(x[j]+h[0][j]*coef[j*3]+h[1][j]*coef[j*3+1]+x[j]*coef[j*3+2]);h[0]=std::move(h[1]);h[1]=std::move(original);return x;}
 struct HC {V input,post,res;};
 HC pre(const V&x,const std::string&name,bool merge=false){auto&phi=cpu(name+".phi.weight");auto&gamma=cpu(name+".norm_gamma");auto&alpha=cpu(name+(merge?".branch_alpha_pre":".branch_alpha"));auto&beta=cpu(name+(merge?".branch_beta_pre":".branch_beta"));float square=0;for(float v:x)square+=v*v;float inv=1/std::sqrt(square/x.size()+1e-6f);V mix(merge?4:24);for(size_t j=0;j<mix.size();++j){float v=0;for(size_t k=0;k<x.size();++k)v+=x[k]*(phi[j*x.size()+k]*gamma[k]);mix[j]=v*inv;}HC h;h.input.assign(2560,0);h.post.resize(4);h.res.resize(16);for(int j=0;j<4;++j){float g=1/(1+std::exp(-(mix[j]*alpha[0]+beta[j])))+1e-6f;for(int k=0;k<2560;++k)h.input[k]+=g*x[j*2560+k];if(!merge)h.post[j]=2/(1+std::exp(-(mix[j+4]*alpha[1]+beta[j+4])));}for(auto&v:h.input)v=roundbf(v);if(merge)return h;
  for(int j=0;j<16;++j)h.res[j]=mix[j+8]*alpha[2]+beta[j+8];
  for(int i=0;i<4;++i){float maximum=*std::max_element(h.res.begin()+i*4,h.res.begin()+(i+1)*4),s=0;for(int j=0;j<4;++j){h.res[i*4+j]=std::exp(h.res[i*4+j]-maximum);s+=h.res[i*4+j];}for(int j=0;j<4;++j)h.res[i*4+j]=h.res[i*4+j]/s+1e-6f;}
  for(int pass=0;pass<20;++pass){if(pass)for(int i=0;i<4;++i){float s=1e-6f;for(int j=0;j<4;++j)s+=h.res[i*4+j];for(int j=0;j<4;++j)h.res[i*4+j]/=s;}for(int j=0;j<4;++j){float s=1e-6f;for(int i=0;i<4;++i)s+=h.res[i*4+j];for(int i=0;i<4;++i)h.res[i*4+j]/=s;}}return h;
 }
 V post(const V&x,const V&branch,const HC&h){V y(x.size());for(int i=0;i<4;++i)for(int j=0;j<2560;++j){float v=h.post[i]*branch[j];for(int k=0;k<4;++k)v+=h.res[k*4+i]*x[k*2560+j];y[i*2560+j]=roundbf(v);}return y;}
 void rope(V&v,int pos){V copy=v;for(int i=0;i<32;++i){float angle=float(pos)/std::pow(6400000.f,float(2*i)/64);float c=roundbf(std::cos(angle)),s=roundbf(std::sin(angle));v[i]=roundbf(copy[i]*c-copy[i+32]*s);v[i+32]=roundbf(copy[i+32]*c+copy[i]*s);}}
 V attention(const V&x,int layer,int pos){std::string p="model.layers."+std::to_string(layer)+".self_attn";auto qa=norm(mome(linear(p+".q_a_proj",x),p+".qa_conv",pos),p+".q_a_layernorm");auto q=linear(p+".q_b_proj",qa,true);auto kv=linear(p+".kv_a_proj_with_mqa",x);V latent(kv.begin(),kv.begin()+512),kr(kv.begin()+512,kv.end());latent=norm(mome(latent,p+".compresskv_conv",pos),p+".kv_a_layernorm");rope(kr,pos);latent.insert(latent.end(),kr.begin(),kr.end());cache[layer].push_back(latent);
  if(sinks[layer].empty()){auto&sk=cpu(p+".param_sink_compressed_kv");auto&sr=cpu(p+".param_sink_k_pe");for(int i=0;i<128;++i){V v(sk.begin()+i*512,sk.begin()+(i+1)*512);v=norm(v,p+".kv_a_layernorm");v.insert(v.end(),sr.begin()+i*64,sr.begin()+(i+1)*64);sinks[layer].push_back(std::move(v));}}
  auto&weight=w(p+".kv_b_proj.weight");V local;
  for(int head=0;head<6;++head){int offset=(rank*6+head)*192;V no(q.begin()+offset,q.begin()+offset+128),rot(q.begin()+offset+128,q.begin()+offset+192);rope(rot,pos);auto query=matrix(no,static_cast<uint16_t*>(weight.data)+head*256*512,128,512,false);query.insert(query.end(),rot.begin(),rot.end());V scores;float maximum=-1e30f;auto score=[&](const V&key){float v=0;for(int j=0;j<576;++j)v+=query[j]*key[j];v/=std::sqrt(192.f);maximum=std::max(maximum,v);scores.push_back(v);};for(auto&key:cache[layer])score(key);for(auto&key:sinks[layer])score(key);float total=0;for(auto&v:scores){v=std::exp(v-maximum);total+=v;}V value(512,0);size_t index=0;auto accum=[&](const V&key){float prob=scores[index++]/total;for(int j=0;j<512;++j)value[j]+=prob*key[j];};for(auto&key:cache[layer])accum(key);for(auto&key:sinks[layer])accum(key);for(auto&v:value)v=roundbf(v);auto out=matrix(value,static_cast<uint16_t*>(weight.data)+(head*256+128)*512,128,512);local.insert(local.end(),out.begin(),out.end());}
  return linear(p+".o_proj",mome(gather(local),p+".o_conv",pos),true);
 }
 V mlp(const V&x,const std::string&p,bool distributed){auto gate=linear(p+".gate_proj",x,distributed),up=linear(p+".up_proj",x,distributed);for(size_t i=0;i<gate.size();++i)gate[i]=roundbf(gate[i]/(1+std::exp(-gate[i]))*up[i]);return linear(p+".down_proj",gate,distributed);}
 V feedforward(const V&x,int layer){std::string p="model.layers."+std::to_string(layer)+".mlp";if(layer<2)return mlp(x,p,true);auto&gate=cpu(p+".gate.weight");auto&bias=cpu(p+".e_score_correction_bias");V score(256);std::vector<int>order(256);std::iota(order.begin(),order.end(),0);for(int e=0;e<256;++e){float v=0;for(int j=0;j<2560;++j)v+=gate[e*2560+j]*x[j];score[e]=1/(1+std::exp(-v));}std::partial_sort(order.begin(),order.begin()+8,order.end(),[&](int a,int b){float aa=score[a]+bias[a],bb=score[b]+bias[b];return aa==bb?a<b:aa>bb;});float total=0;for(int i=0;i<8;++i)total+=score[order[i]];V y(2560,0);for(int i=0;i<8;++i){int e=order[i];if(e/32!=rank)continue;auto value=mlp(x,p+".experts."+std::to_string(e),false);float scale=score[e]/(total+1e-20f)*2.5f;for(int j=0;j<2560;++j)y[j]+=scale*value[j];}y=sum(y);auto shared=mlp(x,p+".shared_experts",true);for(int j=0;j<2560;++j)y[j]=roundbf(y[j]+shared[j]);return y;}
 V token(int id,int pos){if(pos<0||pos>=512||id<0||id>=151552)throw std::runtime_error("diagnostic decoder token/context bound");auto&embedding=w("model.embed_tokens.weight");std::vector<uint16_t>b(2560);checked(aclrtMemcpy(b.data(),5120,static_cast<uint16_t*>(embedding.data)+size_t(id)*2560,5120,ACL_MEMCPY_DEVICE_TO_HOST),"embedding row");V x;auto row=unpacked(b);for(int j=0;j<4;++j)x.insert(x.end(),row.begin(),row.end());for(int layer=0;layer<46;++layer){std::string p="model.layers."+std::to_string(layer);auto h=pre(x,p+".attn_mhc_module");auto a=attention(norm(h.input,p+".input_layernorm"),layer,pos);x=post(x,norm(a,p+".post_attention_layernorm"),h);h=pre(x,p+".mlp_mhc_module");auto f=feedforward(norm(h.input,p+".pre_mlp_layernorm"),layer);x=post(x,norm(f,p+".post_mlp_layernorm"),h);if(weights.tensors.count(p+".block_post_layernorm.weight"))x=norm(x,p+".block_post_layernorm");for(float v:x)if(!std::isfinite(v))throw std::runtime_error("nonfinite layer "+std::to_string(layer));if(rank==0)std::cerr<<"position="<<pos<<" layer="<<layer<<" rms="<<std::sqrt(std::inner_product(x.begin(),x.end(),x.begin(),0.f)/x.size())<<'\n';}return linear("lm_head",norm(pre(x,"model.merge_mhc_module",true).input,"model.norm"),true);}
};
} // namespace pangu
int main(int argc,char**argv){if(argc<5){std::cerr<<"usage: openpangu_decode LOAD_PLAN_DIR CHECKPOINT NEW_TOKENS TOKEN_ID...\n";return 2;}try{int steps=std::stoi(argv[3]);std::vector<int>prompt;for(int i=4;i<argc;++i)prompt.push_back(std::stoi(argv[i]));if(steps<1||steps>128||prompt.size()+steps>512)throw std::runtime_error("token budget");openpangu::checked(aclInit(nullptr),"init");openpangu::checked(aclrtSetDevice(0),"bootstrap");HcclRootInfo info;openpangu::checked(HcclGetRootInfo(&info),"root");std::vector<std::thread>threads;for(int rank=0;rank<8;++rank)threads.emplace_back([&,rank]{try{openpangu::LoadPlan plan(std::string(argv[1])+"/rank-"+std::to_string(rank)+".bin");openpangu::checked(aclrtSetDevice(plan.device),"device");{pangu::Decoder decoder(plan,argv[2],info);pangu::V logits;int pos=0;for(int token:prompt)logits=decoder.token(token,pos++);for(int i=0;i<steps;++i){int next=int(std::max_element(logits.begin(),logits.end())-logits.begin());if(rank==0)std::cout<<"{\"step\":"<<i<<",\"token\":"<<next<<",\"logit\":"<<logits[next]<<"}"<<std::endl;if(next==148902||i+1==steps)break;logits=decoder.token(next,pos++);}}openpangu::checked(aclrtResetDevice(plan.device),"reset");}catch(const std::exception&e){std::cerr<<"rank="<<rank<<" "<<e.what()<<std::endl;std::_Exit(1);}});for(auto&t:threads)t.join();openpangu::checked(aclFinalize(),"finalize");}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
